DO $fix$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.jury_backend(text,jsonb)'::regprocedure) INTO definition; definition := replace(definition,'SELECT q.* , a.cached INTO j','SELECT q.* INTO j'); definition := replace(definition,'UPDATE public.jury_jobs SET status=''running'',run_token=gen_random_uuid(),deadline=clock_timestamp()+interval ''55 seconds'' WHERE id=j.id RETURNING * INTO j;','UPDATE public.jury_jobs SET status=''running'',run_token=gen_random_uuid(),deadline=clock_timestamp()+interval ''55 seconds'' WHERE id=j.id RETURNING * INTO j; UPDATE public.jury_control SET lease_until=clock_timestamp()+interval ''120 seconds'' WHERE id=true AND active_job=j.id;'); EXECUTE definition; END $fix$;